const ed  = $('Econodata · Empresa').first().json ?? {};
const f   = $('Buscar Fornecedor').first().json;
const qsa = $('Direct Data · QSA e Participação Societária').first().json.retorno ?? {};

function classificarRegime(v) {
  const s = String(v ?? '').toLowerCase();
  if (!s) return 'ND';
  if (s.includes('mei') || s.includes('microempreendedor')) return 'MEI';
  if (s.includes('simples')) return 'Simples Nacional (padrão)';
  if (s.includes('real') || s.includes('arbitrado')) return 'Lucro Real (regime regular IBS/CBS)';
  if (s.includes('presumido')) return 'Lucro Presumido';
  if (s.includes('imune') || s.includes('isent')) return 'Imune/Isento/Não contribuinte';
  return 'ND';
}

function numDecimal(raw) {
  if (raw === null || raw === undefined) return null;
  if (typeof raw === 'number') return Number.isFinite(raw) ? raw : null;
  const v = parseFloat(String(raw).replace(/[^\d.-]/g, ''));
  return Number.isFinite(v) ? v : null;
}

function extrairCapitalSocialQSA(texto) {
  if (!texto) return null;
  const match = String(texto).match(/[\d.,]+/);
  if (!match) return null;
  const num = match[0].replace(/\./g, '').replace(',', '.');
  const valor = parseFloat(num);
  return Number.isFinite(valor) ? valor : null;
}

function parseFaixaReais(raw) {
  if (!raw) return null;
  const nums = String(raw).match(/[\d.]+/g);
  if (!nums || nums.length === 0) return null;
  const valores = nums.map(n => parseFloat(n.replace(/\./g, ''))).filter(Number.isFinite);
  if (valores.length === 0) return null;
  if (valores.length === 1) return valores[0];
  return Math.round((valores[0] + valores[1]) / 2);
}

function dataFundacao() {
  if (ed.dataAbertura) return String(ed.dataAbertura).slice(0, 10);
  if (qsa.dataAbertura) return String(qsa.dataAbertura).split(' ')[0].split('/').reverse().join('-');
  return null;
}

// Extrai o(s) número(s) de uma faixa em texto ("R$ 1.800.001 a R$ 4.800.000")
// e retorna o maior valor (teto da faixa). Funciona também se vier um valor único.
function parseFaixaMax(raw) {
  if (raw === null || raw === undefined) return null;
  if (typeof raw === 'number') return Number.isFinite(raw) ? raw : null;
  const matches = String(raw).match(/[\d.,]+/g);
  if (!matches || matches.length === 0) return null;
  const valores = matches
    .map(m => {
      const s = m.replace(/\./g, '').replace(',', '.'); // BR: ponto=milhar, vírgula=decimal
      const v = parseFloat(s);
      return Number.isFinite(v) ? v : null;
    })
    .filter(v => v !== null);
  return valores.length > 0 ? Math.max(...valores) : null;
}

const hist = $('Agregar Histórico Sócios').first().json ?? {};

const porte = ed.porteEstimado
  ?? (Array.isArray(ed.enquadramentoPorte) ? ed.enquadramentoPorte[0] : null);

return [{
  json: {
    fornecedor_id: f.fornecedor_id,
    razao_social:  ed.razaoSocial  ?? f.razao_social ?? null,
    nome_fantasia: ed.nomeFantasia ?? null,
    uf:            ed.uf     ?? f.uf ?? null,
    cidade:        ed.cidade ?? f.cidade ?? null,
    regime_tributario: classificarRegime(ed.regime_tributario),
    porte: porte ?? null,
    faturamento_estimado: parseFaixaMax(ed.faturamentoPresumidoGrupoEconomico)
  ?? parseFaixaMax(ed.faturamentoAnualPresumido ?? ed.faturamentoPresumido),
    data_fundacao: dataFundacao(),
    capital_social: numDecimal(ed.capitalSocial) ?? extrairCapitalSocialQSA(qsa.capitalSocialQSA),
    em_recuperacao_judicial: qsa.emRecuperacaoJudicial === true ? true : null,
    pct_problematico_socios: hist.pct_problematico_medio ?? null,
    detalhes_socios: hist.detalhes_socios ?? null,

    // ---- agora persistidos de verdade em credscore.fornecedores ----
    situacao_cadastral: ed.situacao ?? null,
    qtd_funcionarios: ed.quantidadeFuncionarios ?? null,
    qtd_filiais: ed.quantidadeFiliais ?? null,
    divida_uniao_total: ed.dividasResumo?.dividas_uniao?.total_dividas_principal ?? null,
    divida_uniao_qtde: ed.dividasResumo?.dividas_uniao?.qtde_dividas_principal ?? null,
    divida_uniao_pct_faturamento: ed.dividasResumo?.dividas_uniao?.percentual_faturamento_principal ?? null,
    divida_uniao_socios_total: ed.dividasResumoSocios?.dividas_uniao?.total_dividas_principal ?? null
  }
}];

